with snapshots as (select j.city_id,s.payload,row_number() over(partition by j.city_id order by s.observed_at) as n from fuel_research_snapshots s join fuel_research_jobs j on j.id=s.job_id where j.campaign_id='hourly-24-cities-20260930-v1' and s.saved_at<='2026-10-01T01:22:26.937Z'), quotes as (select city_id,n,st->>'stationId' sid,p->>'fuel' fuel,k.payment,(p->k.payment->>'price')::numeric price from snapshots cross join lateral jsonb_array_elements(payload->'stations') st cross join lateral jsonb_array_elements(st->'prices') p cross join (values('cash'),('credit')) k(payment) where (p->k.payment->>'price')::numeric>0), common as (select a.city_id,a.n,a.fuel,a.payment,a.sid,a.price before_price,b.price after_price from quotes a join quotes b on b.city_id=a.city_id and b.n=a.n+1 and b.sid=a.sid and b.fuel=a.fuel and b.payment=a.payment), decisions as (select city_id,n,fuel,payment,count(*) candidates,(array_agg(after_price order by before_price,sid))[1]-min(after_price) gap from common group by city_id,n,fuel,payment having count(*)>=5) select count(*) as comparisons,count(*) filter(where gap>0) as losses,max(gap) as worst_gap,percentile_disc(0.95) within group(order by gap) as p95_gap from decisions;
